/**
 * Follow-up — wiersze do Resend.
 * Kandydat: followup_candidate=TRUE/1; albo kolumna candidate pusta i wtedy: is_event_inquiry + nie human + nie needs_human_review + nie skip_client_offer_resend.
 * Wyłączenie: jawne followup_candidate=FALSE/0.
 * Ścisły tylko TRUE z arkusza: env FOLLOWUP_STRICT_CANDIDATE=1.
 * Adres: resend_to → client_to_email → wp_form_client_email → email → emailFrom.
 * eligible: followup_eligible_at lub zapisano_at + FOLLOWUP_DELAY_HOURS (domyślnie 48 h = 2 dni) lub FOLLOWUP_DELAY_DAYS×24.
 * Temat/HTML z arkusza; gdy puste — domyślny krótki mail (wyłącz: FOLLOWUP_NO_MINIMAL_TEMPLATE=1).
 */
function truthyCandidate(v) {
  if (v === true) return true;
  const s = String(v ?? '').trim().toUpperCase();
  return s === 'TRUE' || s === '1' || s === 'TAK' || s === 'YES';
}
function explicitNoFollowup(row) {
  const s = String(row.followup_candidate ?? '').trim().toUpperCase();
  return row.followup_candidate === false || s === 'FALSE' || s === '0';
}
function notSentYet(v) {
  const s = String(v ?? '').trim().toUpperCase();
  if (s === 'TRUE' || s === '1' || v === true) return false;
  if (v === false || s === 'FALSE' || s === '0' || s === '') return true;
  return true;
}
function parseIso(s) {
  if (!s) return null;
  const d = new Date(String(s).trim());
  return Number.isNaN(d.getTime()) ? null : d;
}
function pickRecipient(row) {
  const tryList = [row.resend_to, row.client_to_email, row.wp_form_client_email, row.email];
  for (let i = 0; i < tryList.length; i++) {
    const c = tryList[i];
    if (c && String(c).includes('@')) return String(c).trim();
  }
  const ef = row.emailFrom;
  if (typeof ef === 'string') {
    const m = ef.match(/<([^>\s]+@[^>\s]+)>/);
    if (m) return m[1].trim();
    if (ef.includes('@')) return ef.trim();
  }
  if (ef && typeof ef === 'object') {
    if (ef.address && String(ef.address).includes('@')) return String(ef.address).trim();
  }
  return '';
}
function delayHours() {
  try {
    const eh = String($env.FOLLOWUP_DELAY_HOURS ?? '').trim();
    if (eh !== '') {
      const n = parseInt(eh, 10);
      if (Number.isFinite(n) && n >= 0) return n;
    }
    const ed = String($env.FOLLOWUP_DELAY_DAYS ?? '').trim();
    if (ed !== '') {
      const d = parseInt(ed, 10);
      if (Number.isFinite(d) && d >= 0) return d * 24;
    }
  } catch (e) {}
  return 48;
}
function strictCandidateOnly() {
  try {
    return String($env.FOLLOWUP_STRICT_CANDIDATE || '').trim() === '1';
  } catch (e) {
    return false;
  }
}
function noMinimalTemplate() {
  try {
    return String($env.FOLLOWUP_NO_MINIMAL_TEMPLATE || '').trim() === '1';
  } catch (e) {
    return false;
  }
}
function bypassEligibleDate() {
  try {
    return String($env.FOLLOWUP_BYPASS_ELIGIBLE_DATE || '').trim() === '1';
  } catch (e) {
    return false;
  }
}
function inferCandidateFromInquiry(row) {
  if (!truthyCandidate(row.is_event_inquiry)) return false;
  if (truthyCandidate(row.human)) return false;
  if (truthyCandidate(row.needs_human_review)) return false;
  if (truthyCandidate(row.skip_client_offer_resend)) return false;
  return true;
}
function candidateMissingOrEmpty(row) {
  const fc = row.followup_candidate;
  if (fc === undefined || fc === null) return true;
  return String(fc).trim() === '';
}
function isRowCandidate(row) {
  if (explicitNoFollowup(row)) return false;
  if (strictCandidateOnly()) return truthyCandidate(row.followup_candidate);
  if (truthyCandidate(row.followup_candidate)) return true;
  if (candidateMissingOrEmpty(row) && inferCandidateFromInquiry(row)) return true;
  return false;
}

const DEFAULT_SUBJ = 'Imprezja — w razie pytań: odpowiedź na mail lub telefon 🙂';
const DEFAULT_HTML =
  '<div style="font-family:Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.5;color:#222;">' +
  '<p>Dzień dobry,</p>' +
  '<p>Piszę z biura <strong>Imprezja</strong> — wracam krótko po naszej wiadomości z ofertą. Jeśli nadal szukacie <strong>DJ-a i wodzireja</strong>, chętnie doprecyzujemy wszystko: muzykę, scenariusz, atrakcje — w spokojnym tempie, bez pośpiechu.</p>' +
  '<p><strong>Napiszcie śmiało</strong> — wystarczy odpowiedź na tego maila albo telefon <strong>503&nbsp;836&nbsp;965</strong>.</p>' +
  '<p>Relacje z imprez i opinie:</p>' +
  '<ul style="margin:0 0 1em 1.2em;">' +
  '<li><strong>Facebook:</strong> <a href="https://www.facebook.com/imprezjadamiannowaczyk">facebook.com/imprezjadamiannowaczyk</a></li>' +
  '<li><strong>Instagram:</strong> <a href="https://www.instagram.com/imprezja/">instagram.com/imprezja</a></li>' +
  '</ul>' +
  '<p>Jeśli temat jest już zamknięty, spokojnie zignorujcie tę wiadomość. W przeciwnym razie czekam na sygnał 🙂</p>' +
  '<p>Pozdrawiam serdecznie,<br/><strong>Damian Nowaczyk</strong><br/>DJ / wodzirej Imprezja<br/><a href="https://www.imprezja.pl">www.imprezja.pl</a></p></div>';

const now = new Date();
const dh = delayHours();
const strictMin = noMinimalTemplate();
const out = [];
for (const item of $input.all()) {
  const row = item.json;
  if (!isRowCandidate(row)) continue;
  if (!notSentYet(row.followup_sent)) continue;
  let el = parseIso(row.followup_eligible_at);
  if (!el) {
    const zb = parseIso(row.zapisano_at);
    if (zb) {
      const d = new Date(zb.getTime());
      d.setUTCHours(d.getUTCHours() + dh);
      el = d;
    }
  }
  if (!el) continue;
  if (!bypassEligibleDate() && el > now) continue;
  const to = pickRecipient(row);
  if (!to.includes('@')) continue;
  let subj = String(row.subject_followup_3d || '').trim();
  let html = String(row.html_followup_3d || '').trim();
  if ((!subj || !html) && !strictMin) {
    if (!subj) subj = DEFAULT_SUBJ;
    if (!html) html = DEFAULT_HTML;
  }
  if (!subj || !html) continue;
  const wr = String(row.workflow_run || '').trim();
  if (!wr) continue;
  const resend = row.resend_to && String(row.resend_to).includes('@') ? String(row.resend_to).trim() : to;
  out.push({
    json: { ...row, resend_to: resend, subject_followup_3d: subj, html_followup_3d: html },
    pairedItem: item.pairedItem,
  });
}
return out;

/**
 * Przywróć workflow_run + flagi pod Update (HTTP zwraca tylko odpowiedź Resend).
 */
const httpItems = $input.all();
const rows = $('Code_FilterFollowupEligible').all();
if (httpItems.length !== rows.length) {
  throw new Error('followup: liczba odpowiedzi Resend != liczba wierszy do wysłania');
}
const at = new Date().toISOString();
return httpItems.map((item, i) => ({
  json: {
    workflow_run: String(rows[i].json.workflow_run || '').trim(),
    followup_sent: 'TRUE',
    followup_sent_at: at
  },
  pairedItem: item.pairedItem
}));
